#!/usr/bin/python3
"""Convert a 2D occupancy map (ROS map_server .yaml + image) into a Gazebo world.

Occupied pixels are traced into outlines, simplified into straight segments, and
every segment becomes a thin box wall. The world uses the same x/y frame as the
map, so centerline/raceline CSVs made for the map line up with the walls.

Usage:
    map_to_world.py <map.yaml> <world.sdf> [--wall-height 0.5] [--simplify 1.0] ...
"""

import argparse
import math
import os

import cv2
import numpy as np
import yaml


WORLD_TEMPLATE = """<?xml version="1.0"?>
<!-- Generated by arcsf1tenth_gazebo/map_to_world.py from {map_file} -->
<sdf version="1.9">
  <world name="{name}">
    <physics name="1ms" type="ignored">
      <max_step_size>0.001</max_step_size>
      <real_time_factor>1.0</real_time_factor>
    </physics>

    <plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics" />
    <plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands" />
    <plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster" />
    <plugin filename="gz-sim-sensors-system" name="gz::sim::systems::Sensors">
      <render_engine>ogre2</render_engine>
    </plugin>
    <plugin filename="gz-sim-imu-system" name="gz::sim::systems::Imu" />

    <scene>
      <grid>false</grid>
      <ambient>0.4 0.4 0.4 1</ambient>
      <background>0.7 0.7 0.7 1</background>
    </scene>

    <light type="directional" name="sun">
      <cast_shadows>true</cast_shadows>
      <pose>0 0 10 0 0 0</pose>
      <diffuse>0.8 0.8 0.8 1</diffuse>
      <specular>0.2 0.2 0.2 1</specular>
      <direction>-0.5 0.1 -0.9</direction>
    </light>

    <model name="ground_plane">
      <static>true</static>
      <link name="link">
        <collision name="collision">
          <geometry><plane><normal>0 0 1</normal><size>{ground_size} {ground_size}</size></plane></geometry>
        </collision>
        <visual name="visual">
          <geometry><plane><normal>0 0 1</normal><size>{ground_size} {ground_size}</size></plane></geometry>
          <material>
            <ambient>0.6 0.6 0.6 1</ambient>
            <diffuse>0.6 0.6 0.6 1</diffuse>
          </material>
        </visual>
      </link>
    </model>

    <model name="walls">
      <static>true</static>
      <link name="link">
{walls}
      </link>
    </model>
  </world>
</sdf>
"""

WALL_TEMPLATE = """        <collision name="wall_{i}_collision">
          <pose>{x:.4f} {y:.4f} {z:.4f} 0 0 {yaw:.5f}</pose>
          <geometry><box><size>{length:.4f} {thickness:.4f} {height:.4f}</size></box></geometry>
        </collision>
        <visual name="wall_{i}_visual">
          <pose>{x:.4f} {y:.4f} {z:.4f} 0 0 {yaw:.5f}</pose>
          <geometry><box><size>{length:.4f} {thickness:.4f} {height:.4f}</size></box></geometry>
          <material>
            <ambient>0.15 0.15 0.15 1</ambient>
            <diffuse>0.15 0.15 0.15 1</diffuse>
          </material>
        </visual>"""


def load_occupied_mask(map_yaml, unknown_is_wall=False):
    """Return (mask, resolution, origin) where mask is 255 for occupied pixels."""
    with open(map_yaml) as f:
        meta = yaml.safe_load(f)

    image_path = os.path.join(os.path.dirname(os.path.abspath(map_yaml)), meta['image'])
    image = cv2.imread(image_path, cv2.IMREAD_GRAYSCALE)
    if image is None:
        raise FileNotFoundError(f'Cannot read map image: {image_path}')

    # Same rule as nav2 map_server (trinary mode)
    occupancy = image.astype(np.float32) / 255.0
    if not meta.get('negate', 0):
        occupancy = 1.0 - occupancy
    # unknown_is_wall: anything that is not clearly free (near white) becomes a wall,
    # which closes corridors that end in unexplored space
    threshold = 0.02 if unknown_is_wall else meta['occupied_thresh']
    mask = np.where(occupancy > threshold, 255, 0).astype(np.uint8)

    # The map edge is the end of the known world: close tracks that run off the image
    mask[[0, -1], :] = 255
    mask[:, [0, -1]] = 255

    return mask, float(meta['resolution']), meta['origin']


def extract_segments(mask, simplify_px, min_area_px):
    """Trace occupied regions and return their outlines as pixel line segments."""
    # Remove single-pixel noise before tracing
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))

    contours, _ = cv2.findContours(mask, cv2.RETR_LIST, cv2.CHAIN_APPROX_NONE)
    segments = []
    for contour in contours:
        if cv2.contourArea(contour) < min_area_px and len(contour) < min_area_px:
            continue
        polygon = cv2.approxPolyDP(contour, simplify_px, closed=True).reshape(-1, 2)
        if len(polygon) < 2:
            continue
        for a, b in zip(polygon, np.roll(polygon, -1, axis=0)):
            if not np.array_equal(a, b):
                segments.append((a, b))
    return segments


def pixel_to_world(px, height, resolution, origin):
    """Pixel (col, row) -> map frame (x, y). Image row 0 is the top of the map."""
    col, row = px
    x = origin[0] + (col + 0.5) * resolution
    y = origin[1] + (height - row - 0.5) * resolution
    return x, y


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('map_yaml', help='map_server yaml file')
    parser.add_argument('world_sdf', help='output Gazebo world file')
    parser.add_argument('--name', default='track', help='Gazebo world name')
    parser.add_argument('--wall-height', type=float, default=0.5, help='[m] must be above the lidar')
    parser.add_argument('--wall-thickness', type=float, default=0.05, help='[m]')
    parser.add_argument('--simplify', type=float, default=1.0,
                        help='[px] max deviation when merging outline pixels into straight walls')
    parser.add_argument('--unknown-is-wall', action='store_true',
                        help='treat unknown/gray pixels as walls (closes open corridor ends)')
    parser.add_argument('--min-area', type=float, default=6.0, help='[px] ignore smaller blobs (noise)')
    args = parser.parse_args()

    mask, resolution, origin = load_occupied_mask(args.map_yaml, args.unknown_is_wall)
    height_px, width_px = mask.shape
    segments = extract_segments(mask, args.simplify, args.min_area)

    walls = []
    for i, (a, b) in enumerate(segments):
        ax, ay = pixel_to_world(a, height_px, resolution, origin)
        bx, by = pixel_to_world(b, height_px, resolution, origin)
        length = math.hypot(bx - ax, by - ay) + args.wall_thickness  # overlap at corners
        walls.append(WALL_TEMPLATE.format(
            i=i,
            x=(ax + bx) / 2.0, y=(ay + by) / 2.0, z=args.wall_height / 2.0,
            yaw=math.atan2(by - ay, bx - ax),
            length=length, thickness=args.wall_thickness, height=args.wall_height,
        ))

    ground_size = math.ceil(max(width_px, height_px) * resolution * 1.5)
    os.makedirs(os.path.dirname(os.path.abspath(args.world_sdf)), exist_ok=True)
    with open(args.world_sdf, 'w') as f:
        f.write(WORLD_TEMPLATE.format(
            map_file=os.path.basename(args.map_yaml), name=args.name,
            ground_size=ground_size, walls='\n'.join(walls),
        ))

    print(f'{args.world_sdf}: {len(walls)} walls from {width_px}x{height_px} px map '
          f'({width_px * resolution:.1f} x {height_px * resolution:.1f} m)')


if __name__ == '__main__':
    main()
